package realtime
import("encoding/base64";"bytes";"errors")
type ParityDualFixture struct{Method,Scope,ID string;Exclude []string;Frame []byte;Loopback,Failure,GlobalRoom bool}
type parityDualPublisher struct{h *Hub;clients []*Client;f ParityDualFixture;calls []any;before []int;eventID string}
func(p *parityDualPublisher)PublishWithID(scope,id,exclude string,frame []byte,eventID string)error{p.eventID=eventID;for _,c:=range p.clients{p.before=append(p.before,len(c.send))};p.calls=append(p.calls,[]string{scope,id,exclude,base64.StdEncoding.EncodeToString(frame),"EVENT"});if p.f.Loopback{deliverEnvelope(p.h,nil,nil,envelope{Scope:scope,ScopeID:id,WorkspaceID:exclude,PayloadJSON:string(frame),EventID:eventID})};if p.f.Failure{return errors.New("unavailable")};return nil}
func ParityDual(f ParityDualFixture)any{M.Reset();h:=NewHub();clients:=[]*Client{};for _,pair:=range [][2]string{{"w","u"},{"w","v"},{"x","u"}}{c:=&Client{hub:h,workspaceID:pair[0],userID:pair[1],send:make(chan []byte,256)};h.registerClient(c);clients=append(clients,c)};h.subscribe(clients[0],"chat","c");if f.GlobalRoom{h.subscribe(clients[0],"global","all")};p:=&parityDualPublisher{h:h,clients:clients,f:f,calls:[]any{},before:[]int{}};d:=NewDualWriteBroadcaster(h,p);switch f.Method{case "scope":d.BroadcastToScope(f.Scope,f.ID,f.Frame);case "workspace":d.BroadcastToWorkspace(f.ID,f.Frame);case "user":d.SendToUser(f.ID,f.Frame,f.Exclude...);case "global":d.Broadcast(f.Frame)};queues:=[][]string{};for _,c:=range clients{one:=[]string{};for len(c.send)>0{raw:=<-c.send;raw=bytes.ReplaceAll(raw,[]byte(p.eventID),[]byte("EVENT"));one=append(one,base64.StdEncoding.EncodeToString(raw))};queues=append(queues,one)};return map[string]any{"calls":p.calls,"before":p.before,"queues":queues,"sent":M.MessagesSentTotal.Load()}}
